#!/usr/bin/env python3
"""taskman - a single-file task list reporter over a TSV file.

Columns: id, status, priority, tags, title. Tags are comma separated.
Everything below is the current, shipped behaviour.
"""
import argparse
import contextlib
import dataclasses
import sys
from typing import List, Optional

STATUSES = ("open", "done", "blocked")


class TaskError(Exception):
    pass


class BadRow(TaskError):
    def __init__(self, line):
        super().__init__("bad row on line %d" % line)
        self.line = line


class UnknownStatus(TaskError):
    def __init__(self, status):
        super().__init__("unknown status %r" % status)
        self.status = status


@dataclasses.dataclass
class Task:
    id: int
    status: str
    priority: int
    tags: List[str]
    title: str

    def matches(self, status=None, tag=None):
        if status is not None and self.status != status:
            return False
        if tag is not None and tag not in self.tags:
            return False
        return True

    def render(self):
        return "#%d [%s] p%d %s" % (self.id, self.status, self.priority, self.title)


def parse_line(line, lineno):
    parts = line.rstrip("\n").split("\t")
    if len(parts) != 5:
        raise BadRow(lineno)
    raw_id, status, raw_priority, raw_tags, title = parts
    try:
        task_id = int(raw_id)
        priority = int(raw_priority)
    except ValueError:
        raise BadRow(lineno)
    if status not in STATUSES:
        raise BadRow(lineno)
    tags = [t.strip() for t in raw_tags.split(",") if t.strip()]
    if not title.strip():
        raise BadRow(lineno)
    return Task(task_id, status, priority, tags, title)


@contextlib.contextmanager
def open_store(path):
    fh = open(path, "r", encoding="utf-8")
    try:
        tasks = []
        for lineno, line in enumerate(fh, 1):
            if lineno == 1:
                continue
            if not line.strip():
                continue
            tasks.append(parse_line(line, lineno))
        yield tasks
    finally:
        fh.close()


SORT_KEYS = {
    "priority": lambda t: (t.priority, t.id),
    "id": lambda t: (t.id,),
    "title": lambda t: (t.title, t.id),
}


def select(tasks, status=None, tag=None, limit=None, sort="priority"):
    """NOTE: --limit is applied to the rows as read, BEFORE any filtering."""
    rows = tasks[:limit] if limit is not None else list(tasks)
    if status is not None and status not in STATUSES:
        raise UnknownStatus(status)
    rows = [t for t in rows if t.matches(status=status, tag=tag)]
    return sorted(rows, key=SORT_KEYS[sort])


def count_statuses(tasks):
    counts = {s: 0 for s in STATUSES}
    for t in tasks:
        counts[t.status] += 1
    return counts


def tag_table(tasks):
    counts = {}
    for t in tasks:
        for tag in t.tags:
            counts.setdefault(tag, []).append(t.id)
    rows = [(tag, len(ids), ids) for tag, ids in counts.items()]
    rows.sort(key=lambda r: (-r[1], r[0]))
    return rows


def find(tasks, task_id):
    for t in tasks:
        if t.id == task_id:
            return t
    return None


def cmd_list(args, tasks, out):
    rows = select(tasks, status=args.status, tag=args.tag,
                  limit=args.limit, sort=args.sort)
    for t in rows:
        out.write(t.render() + "\n")
    return 0


def cmd_stats(args, tasks, out):
    counts = count_statuses(tasks)
    out.write(" ".join("%s=%d" % (s, counts[s]) for s in STATUSES) + "\n")
    out.write("total=%d\n" % len(tasks))
    prio = {}
    for t in tasks:
        prio[t.priority] = prio.get(t.priority, 0) + 1
    out.write(" ".join("p%d=%d" % (p, prio[p]) for p in sorted(prio)) + "\n")
    return 0


def cmd_tags(args, tasks, out):
    for tag, n, ids in tag_table(tasks):
        out.write("%s %d %s\n" % (tag, n, ",".join(str(i) for i in sorted(ids))))
    return 0


def cmd_show(args, tasks, out):
    t = find(tasks, args.id)
    if t is None:
        sys.stderr.write("error: no task %d\n" % args.id)
        return 6
    out.write("id: %d\n" % t.id)
    out.write("status: %s\n" % t.status)
    out.write("priority: %d\n" % t.priority)
    out.write("tags: %s\n" % (", ".join(t.tags) if t.tags else "-"))
    out.write("title: %s\n" % t.title)
    return 0


def build_parser():
    p = argparse.ArgumentParser(prog="taskman")
    p.add_argument("--file", required=True)
    sub = p.add_subparsers(dest="cmd", required=True)

    lst = sub.add_parser("list")
    lst.add_argument("--status")
    lst.add_argument("--tag")
    lst.add_argument("--limit", type=int)
    lst.add_argument("--sort", choices=sorted(SORT_KEYS), default="priority")
    lst.set_defaults(func=cmd_list)

    st = sub.add_parser("stats")
    st.set_defaults(func=cmd_stats)

    tg = sub.add_parser("tags")
    tg.set_defaults(func=cmd_tags)

    sh = sub.add_parser("show")
    sh.add_argument("id", type=int)
    sh.set_defaults(func=cmd_show)
    return p


def main(argv=None):
    args = build_parser().parse_args(argv)
    try:
        with open_store(args.file) as tasks:
            return args.func(args, tasks, sys.stdout)
    except FileNotFoundError:
        sys.stderr.write("error: cannot read %s\n" % args.file)
        return 3
    except UnknownStatus as exc:
        sys.stderr.write("error: unknown status '%s'\n" % exc.status)
        return 4
    except BadRow as exc:
        sys.stderr.write("error: bad row on line %d\n" % exc.line)
        return 5


if __name__ == "__main__":
    sys.exit(main())
